import sys

input_data = sys.stdin.read().strip().splitlines()
n, m = map(int, input_data[0].split())
grid = input_data[1:]

row_count = [0] * n
col_count = [0] * m
total_walls = 0

for i in range(n):
    for j in range(m):
        if grid[i][j] == '*':
            row_count[i] += 1
            col_count[j] += 1
            total_walls += 1

for i in range(n):
    for j in range(m):
        bomb_destroy = row_count[i] + col_count[j]
        if grid[i][j] == '*':
            bomb_destroy -= 1
        if bomb_destroy == total_walls:
            print("YES")
            print(i + 1, j + 1)
            sys.exit()

print("NO")
